const LEGACY='taman-main-v1',PREFIX='taman-main-download-',MARKER='./__offline-ready';
const ASSETS=['./','./index.html','./style.css','./app.mjs','./model.mjs','./progress.mjs','./gallery.mjs','./games.mjs','./art.mjs','./interactions.mjs','./narration.mjs','./audio-catalog.mjs','./audio/catalog.json','./garden.svg','./icon.svg','./manifest.webmanifest'];
// Playback can leave partial (206) media in the HTTP cache. Offline packages need full responses.
const fullRequests=paths=>paths.map(path=>new Request(new URL(path,self.location.href),{cache:'reload'}));
async function activeCache(){const names=await caches.keys();for(const name of names.reverse()){if(name===LEGACY)return name;if(name.startsWith(PREFIX)&&(await (await caches.open(name)).match(MARKER)))return name}return null}
self.addEventListener('install',e=>{self.skipWaiting()});
self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));
self.addEventListener('message',e=>{if(e.data?.type==='DOWNLOAD')e.waitUntil((async()=>{const name=PREFIX+Date.now()+'-'+Math.random().toString(36).slice(2);let stage='storage';try{const cache=await caches.open(name);stage='assets';await cache.addAll(fullRequests(ASSETS));stage='catalog';const catalog=await (await cache.match('./audio/catalog.json')).json();if(catalog.language!=='en')throw Error('wrong-language');const audio=[...new Set(Object.values(catalog.clips).flat())];for(let i=0;i<audio.length;i+=12){stage='audio:'+i;await cache.addAll(fullRequests(audio.slice(i,i+12).map(p=>'./'+p)))}stage='marker';await cache.put(MARKER,new Response('ready:en-v1'));e.ports[0]?.postMessage({ok:true});const names=await caches.keys();await Promise.all(names.filter(n=>n!==name&&(n===LEGACY||n.startsWith(PREFIX))).map(n=>caches.delete(n)))}catch(error){await caches.delete(name);e.ports[0]?.postMessage({ok:false,stage,error:{name:error.name,message:error.message}})}})())});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith((async()=>{try{return await fetch(e.request)}catch{const name=await activeCache();if(name){const cache=await caches.open(name);const cached=await cache.match(e.request);if(cached)return cached;if(e.request.mode==='navigate'){const index=await cache.match('./index.html');if(index)return index}}return Response.error()}})())});
